CREATE TABLE administrators (id TEXT PRIMARY KEY CHECK(id='admin'), username TEXT NOT NULL UNIQUE, password TEXT NOT NULL, created_at INTEGER NOT NULL);
CREATE TABLE sessions (hash TEXT PRIMARY KEY, csrf TEXT NOT NULL, expires INTEGER NOT NULL);
CREATE TABLE settings (key TEXT PRIMARY KEY, value TEXT NOT NULL);
CREATE TABLE storage_backends (id TEXT PRIMARY KEY, name TEXT NOT NULL, type TEXT NOT NULL CHECK(type IN ('local','s3')), config TEXT NOT NULL, enabled INTEGER NOT NULL DEFAULT 1, is_default INTEGER NOT NULL DEFAULT 0);
CREATE UNIQUE INDEX one_default_storage ON storage_backends(is_default) WHERE is_default=1;
CREATE TABLE folders (id TEXT PRIMARY KEY, parent_id TEXT REFERENCES folders(id) ON DELETE RESTRICT, name TEXT NOT NULL, description TEXT NOT NULL DEFAULT '', cover_id TEXT, visibility TEXT NOT NULL DEFAULT 'private' CHECK(visibility IN ('public','private')), effective_visibility TEXT NOT NULL DEFAULT 'private', storage_id TEXT REFERENCES storage_backends(id), sort_order INTEGER NOT NULL DEFAULT 0, system INTEGER NOT NULL DEFAULT 0, created_at INTEGER NOT NULL);
CREATE INDEX folder_parent ON folders(parent_id,sort_order);
CREATE TABLE images (id TEXT PRIMARY KEY, folder_id TEXT NOT NULL REFERENCES folders(id) ON DELETE RESTRICT, storage_id TEXT NOT NULL REFERENCES storage_backends(id), object_key TEXT NOT NULL, thumb_key TEXT NOT NULL, name TEXT NOT NULL, format TEXT NOT NULL, mime TEXT NOT NULL, size INTEGER NOT NULL, width INTEGER NOT NULL, height INTEGER NOT NULL, checksum TEXT NOT NULL, visibility TEXT NOT NULL DEFAULT 'private', effective_visibility TEXT NOT NULL DEFAULT 'private', access_version INTEGER NOT NULL DEFAULT 1, state TEXT NOT NULL DEFAULT 'ready', thumbnail_state TEXT NOT NULL DEFAULT 'pending', tags TEXT NOT NULL DEFAULT '[]', description TEXT NOT NULL DEFAULT '', created_at INTEGER NOT NULL, deleted_at INTEGER);
CREATE INDEX image_candidates ON images(effective_visibility,state,deleted_at,folder_id,id);
CREATE INDEX image_folder ON images(folder_id,created_at,id);
CREATE INDEX image_deleted ON images(deleted_at);
CREATE TABLE api_keys (id TEXT PRIMARY KEY, name TEXT NOT NULL, hash TEXT NOT NULL UNIQUE, prefix TEXT NOT NULL, permissions TEXT NOT NULL, expires INTEGER, revoked INTEGER NOT NULL DEFAULT 0, last_used INTEGER, rate_limit INTEGER NOT NULL DEFAULT 120, created_at INTEGER NOT NULL);
CREATE TABLE api_grants (id INTEGER PRIMARY KEY, key_id TEXT NOT NULL REFERENCES api_keys(id) ON DELETE CASCADE, kind TEXT NOT NULL, resource_id TEXT NOT NULL DEFAULT '', descendants INTEGER NOT NULL DEFAULT 0);
CREATE INDEX grant_key ON api_grants(key_id);
CREATE TABLE random_endpoints (id TEXT PRIMARY KEY, kind TEXT NOT NULL, folder_id TEXT REFERENCES folders(id) ON DELETE CASCADE, name TEXT NOT NULL, description TEXT NOT NULL DEFAULT '', visibility TEXT NOT NULL DEFAULT 'private', enabled INTEGER NOT NULL DEFAULT 0, mode TEXT NOT NULL DEFAULT 'image', include_children INTEGER NOT NULL DEFAULT 0, rate_limit INTEGER NOT NULL DEFAULT 60, calls INTEGER NOT NULL DEFAULT 0, successes INTEGER NOT NULL DEFAULT 0, failures INTEGER NOT NULL DEFAULT 0, last_called INTEGER);
CREATE UNIQUE INDEX one_folder_endpoint ON random_endpoints(folder_id) WHERE kind='folder';
CREATE TABLE random_rules (id INTEGER PRIMARY KEY, endpoint_id TEXT NOT NULL REFERENCES random_endpoints(id) ON DELETE CASCADE, kind TEXT NOT NULL, resource_id TEXT NOT NULL, descendants INTEGER NOT NULL DEFAULT 0);
CREATE INDEX rule_endpoint ON random_rules(endpoint_id);
CREATE TABLE jobs (id TEXT PRIMARY KEY, image_id TEXT REFERENCES images(id) ON DELETE CASCADE, kind TEXT NOT NULL, state TEXT NOT NULL DEFAULT 'pending', attempts INTEGER NOT NULL DEFAULT 0, next_run INTEGER NOT NULL DEFAULT 0, error TEXT, created_at INTEGER NOT NULL);
CREATE INDEX jobs_pending ON jobs(state,next_run);
CREATE TABLE upload_operations (id TEXT PRIMARY KEY, storage_id TEXT NOT NULL REFERENCES storage_backends(id), object_key TEXT NOT NULL, thumb_key TEXT NOT NULL, temp_path TEXT NOT NULL, state TEXT NOT NULL, created_at INTEGER NOT NULL);
CREATE TABLE cleanup_objects (id TEXT PRIMARY KEY, storage_id TEXT NOT NULL REFERENCES storage_backends(id), object_key TEXT NOT NULL, attempts INTEGER NOT NULL DEFAULT 0, next_run INTEGER NOT NULL DEFAULT 0, error TEXT);
